function validate([digits]) {
  if (digits.length < 3 || digits.length > 100) return 'digits needs 3 to 100 entries.';
  if (!digits.every(d => Number.isInteger(d) && d >= 0 && d <= 9)) return 'Every entry is a digit from 0 to 9.';
  return null;
}

