function findEvenNumbers(digits) {
  const count = new Array(10).fill(0);
  for (const digit of digits) {
    count[digit]++;
  }

  const result = [];
  for (let value = 100; value < 1000; value += 2) {
    const need = new Array(10).fill(0);
    need[Math.floor(value / 100)]++;
    need[Math.floor(value / 10) % 10]++;
    need[value % 10]++;
    if (need.every((times, digit) => times <= count[digit])) {
      result.push(value);
    }
  }
  return result;
}

