function generate(rand, size) {
  if (size === 'large') {
    const n = 60 + Math.floor(rand() * 41);
    const pool = Array.from({ length: 10 }, (_, d) => d).filter(() => rand() < 0.75);
    if (pool.length === 0) pool.push(4);
    return [Array.from({ length: n }, () => pool[Math.floor(rand() * pool.length)])];
  }
  const n = 3 + Math.floor(rand() * 6);
  // A small pool of digit values makes repeats, zeros and odd-only inputs common.
  const pool = Array.from({ length: 1 + Math.floor(rand() * 4) }, () => Math.floor(rand() * 10));
  return [Array.from({ length: n }, () => pool[Math.floor(rand() * pool.length)])];
}
